import {COURSE,materials,elements,readable,sources} from './model.js';
import {esc,icon,btn,link,empty,search,notice} from './ui.js';
const types={article:'Статья',file:'Файл',video:'Видео',assessment:'Тест',scorm:'SCORM'};
const typeIcon=t=>icon(({article:'book',file:'attachment',video:'ds-play',assessment:'task'})[t]||'book');
export function catalog(s){
 const courses=[{id:101,name:COURSE,desc:'Регистрация, передача сложных случаев и понятная обратная связь.',count:8,duration:25,category:'service',kind:'course'},{id:102,name:'Как сообщать статус обращения',desc:'Короткий курс о промежуточных ответах клиенту.',count:1,duration:4,category:'communication',kind:'course'},{id:103,name:'Регистрация обращения без ошибок',desc:'Практические рекомендации для первой линии.',count:1,duration:5,category:'service',kind:'course'}];
 const shown=courses.filter(c=>(s.category==='all'||c.category===s.category)&&(s.kind==='all'||c.kind===s.kind)&&c.name.toLowerCase().includes(s.search.toLowerCase()));
 return `<div class="page-head"><h1>Каталог</h1></div><div class="catalog-filters row wrap"><label class="filter-select"><span>Тип обучения</span><select id="kind"><option value="all">Все типы</option><option value="course" ${s.kind==='course'?'selected':''}>Онлайн-курс</option><option value="program" ${s.kind==='program'?'selected':''}>Программа</option></select></label><label class="filter-select"><span>Категория</span><select id="category"><option value="all">Все категории</option><option value="service" ${s.category==='service'?'selected':''}>Клиентский сервис</option><option value="communication" ${s.category==='communication'?'selected':''}>Коммуникации</option></select></label>${(s.category!=='all'||s.search||s.kind!=='all')?btn('Сбросить','reset-search','tertiary'):''}</div><div class="section-heading"><h2>Курсы <span class="muted">${shown.length}</span></h2><span class="muted">По названию</span></div>${shown.length?`<div class="course-grid">${shown.map(c=>`<a class="course-card" href="#/learning/course/${c.id}"><div class="course-cover">${icon('book')}<span>Клиентский сервис</span></div><div class="course-info"><span class="muted small">Онлайн-курс</span><h3>${c.name}</h3><p class="muted">${c.desc}</p><div class="course-meta">${icon('clock')} ${c.duration} мин <span>· ${c.count} элементов</span></div><div class="course-bottom"><span>Доступен для изучения</span>${icon('arrow-right')}</div></div></a>`).join('')}</div>`:empty('Ничего не найдено','Измените запрос или сбросьте фильтры.',btn('Сбросить фильтры','reset-search','secondary'))}`;
}
function toc(s,id='register',courseId='101'){const list=courseId==='102'?elements.filter(e=>e.id==='status'):courseId==='103'?elements.filter(e=>e.id==='register'):elements;return `<aside class="course-toc"><h3>Содержание курса</h3><p class="small muted">Изучено ${s.completed.filter(x=>list.some(e=>e.id===x)).length} из ${list.length}</p>${list.map(e=>link(`${typeIcon(e.type)}<span>${esc(e.name)}<small>${types[e.type]} · ${e.duration}</small></span>${s.completed.includes(e.id)?'<span aria-label="Изучено">✓</span>':''}`,`/learning/play/${courseId}?item=${e.id}`,`toc-item ${e.id===id?'active':''}`)).join('')}</aside>`;}
export function course(s,id='101'){
 if(!['101','102','103'].includes(id)){if(s.role!=='author')return empty('Курс недоступен','Выберите опубликованный курс в каталоге.',link('В каталог','/catalog','btn'));const c=s.savedCourses.find(x=>x.id===id);if(!c)return empty('Черновик не найден','Вернитесь в редактор.',link('К курсам','/editor/courses'));return `<div class="page-head"><h1>${esc(c.name)}</h1>${link('В редактор','/editor/courses/'+encodeURIComponent(id)+'/lectures','btn')}</div>${notice('Предпросмотр черновика · курс не опубликован')}<article class="article-body">${c.blocks.map(b=>`<h2>${esc(b.name)}</h2><p>${esc(b.text||'Готовый элемент библиотеки')}</p>`).join('')}</article>`;}
 const name=id==='102'?materials[2].name:id==='103'?'Регистрация обращения без ошибок':COURSE;const first=id==='102'?'status':'register';
 return `<div class="page-head">${link(icon('arrow-left')+' В каталог','/catalog','back')}</div><div class="course-layout"><div class="course-main"><span class="tag">Онлайн-курс</span><h1 class="large-title">${name}</h1><p class="muted">Клиентский сервис</p><div class="row mt">${link('Начать обучение',`/learning/play/${id}?item=${first}`,'btn primary')}<span class="muted">${id==='101'?'30 минут · 8 элементов':'5 минут · 1 элемент'}</span></div><nav class="tabs"><button class="active">Описание</button></nav><article class="article-body"><h2>О курсе</h2><p>Как зарегистрировать обращение, определить сложный случай и сообщить клиенту следующий шаг. Разберём действия первой линии на понятных примерах.</p><h2>Чему вы научитесь</h2><ul><li>Собирать необходимые сведения об обращении.</li><li>Готовить передачу сложного случая эксперту.</li><li>Сообщать статус без неподтверждённых обещаний.</li></ul></article></div>${toc(s,'',id)}</div>`;
}
export function knowledge(s,route){const isArticle=route.includes('/article/');const m=route.endsWith('105')?materials[4]:materials[3];const list=sources(s).filter(x=>x.kind.includes('базы')&&x.name.toLowerCase().includes(s.search.toLowerCase()));return `<div class="page-head"><h1>База знаний</h1></div><div class="knowledge-layout"><aside class="knowledge-tree"><h3>Разделы</h3>${link(icon('sg-folder-outlined')+' Все материалы','/documents','nav-link')} ${link(icon('sg-folder-outlined')+' Клиентский сервис','/documents/all/10','nav-link active')}<div class="nav-sub muted">Обработка обращений</div></aside><section class="knowledge-content">${isArticle?`${link(icon('arrow-left')+' К материалам','/documents/all/10','back')}${readable(m,s)?`<article class="article-body"><span class="muted small">Статья · Клиентский сервис</span><h1>${m.name}</h1><p class="muted">Обновлено 27 октября 2026</p><h2 id="source-fragment">${m.section}</h2><p>${m.body}</p><h2>Пример проверки</h2><p>Что произошло? Какой результат ожидался? Что уже проверили? Какой вопрос нужно решить?</p><div class="row mt">${btn('Спросить помощника','context-ask','secondary')}</div></article>`:empty('Материал недоступен','Выберите другой материал в базе знаний.')}`:`<div class="row between mb"><h2>Клиентский сервис</h2>${search(s.search,'kb-search','Поиск по базе знаний')}</div>${list.length?list.map(m=>`<div class="material-row">${icon('book')}<div class="grow">${link(m.name,m.route)}<p class="small muted">Статья · Обработка обращений</p></div>${link(icon('arrow-right'),m.route,'icon-btn')}</div>`).join(''):empty('Ничего не найдено','Попробуйте другой запрос.')}`}</section></div>`;}
export function player(s,route){const id=new URLSearchParams(route.split('?')[1]).get('item')||'register';const courseId=route.split('/')[3].split('?')[0];const e=elements.find(x=>x.id===id)||elements[0];const m=materials.find(x=>x.id===id);let content='';
 if(e.type==='article'&&id!=='link')content=readable(m,s)?`<article class="article-body"><span class="muted small">${types[e.type]}</span><h1>${e.name}</h1><h2 id="source-fragment">${m.section}</h2><p>${m.body}</p><h2>Проверим на примере</h2><p>Сотрудник первой линии получил повторное обращение. Он зафиксировал ситуацию и то, что уже проверил, затем сформулировал вопрос для эксперта.</p>${btn('Объяснить этот материал','context-ask','secondary')}<div class="row mt">${btn('Изучено, дальше','complete-article','primary',`data-id="${id}"`)}</div></article>`:empty('Материал недоступен','Доступ изменился. Вернитесь к содержанию курса.');
 if(id==='link')content=`<article class="article-body"><h1>${e.name}</h1><p>Откройте связанную статью базы знаний.</p>${link('Частые ошибки при регистрации обращений','/documents/all/10/article/104','btn secondary')}<p class="small muted mt">Ссылка внутри текстового элемента курса.</p></article>`;
 if(id==='file')content=`<article class="article-body"><span class="tag">PDF</span><h1>${e.name}</h1><div class="document-preview"><h2>Перед передачей обращения</h2><p>1. Опишите ситуацию.</p><p>2. Укажите ожидаемый результат.</p><p>3. Перечислите выполненные действия.</p><p>4. Сформулируйте вопрос эксперту.</p></div><a class="btn" download href="assets/checklist.txt">${icon('sg-download')} Скачать материал</a></article>`;
 if(id==='video')content=`<article class="article-body"><span class="tag">Видео</span><h1>${e.name}</h1><div class="video-stub">${icon('ds-play')}<p>Демонстрационный видеоэлемент</p><p class="small muted">Видеофайл не подключён</p></div></article>`;
 if(id==='scorm')content=`<article class="article-body"><span class="tag">SCORM</span><h1>${e.name}</h1><div class="video-stub"><p>Демонстрационный SCORM-элемент</p><p class="hint">Пакет не подключён. Тьютор не анализирует его содержимое.</p></div></article>`;
 if(id==='test')content=test(s);
 return `<div class="page-head">${link(icon('arrow-left')+' К курсу',`/learning/course/${courseId}`,'back')}<span class="muted small">${COURSE}</span></div><div class="course-layout"><div class="course-main">${content}</div>${toc(s,id,courseId)}</div>`;
}
function test(s){const t=s.test;if(t.status==='start')return `<article class="article-body"><span class="tag">Тест</span><h1>Проверка знаний</h1><p>Проверьте, как вы усвоили порядок работы с обращениями.</p><div class="info-row"><span>Вопросов</span><b>1</b></div><div class="info-row"><span>Время</span><span>Без ограничения</span></div><div class="info-row"><span>Правильные ответы</span><span>Не показываются</span></div>${btn('Начать тест','start-test','primary')}</article>`;if(t.status==='finished')return `<article class="article-body"><span class="tag">Тест завершён</span><h1>Результат попытки</h1><p>Ответ сохранён</p><p>Правильные ответы и подробный разбор скрыты настройками теста.</p>${link('Вернуться к материалам','/learning/play/101?item=register','btn primary')}</article>`;return `<article class="article-body"><span class="muted">Вопрос 1 из 1</span><h1>Что необходимо зафиксировать перед передачей обращения?</h1><form id="test-form" class="stack mt">${['Описание ситуации и выполненные действия','Только имя сотрудника','Только дату обращения'].map((a,i)=>`<label class="answer-option"><input type="radio" name="test-answer" value="${i}" ${t.answer===String(i)?'checked':''}><span>${a}</span></label>`).join('')}<div>${btn('Завершить тест','finish-test','primary',t.answer===null?'disabled':'')}</div></form></article>`;}
